// Extrai o texto do CSV retornado pelo HTTP Request e converte em JSON estruturado
const item = $input.first().json;
let rawCsv = '';

if (typeof item === 'string') {
  rawCsv = item;
} else if (item.data && typeof item.data === 'string') {
  rawCsv = item.data;
} else {
  rawCsv = Object.keys(item).join(',');
}

const lines = rawCsv.trim().split(/\r?\n/);
const headers = lines[0].split(',').map(h => h.trim());

const investimentos = [];
for (let i = 1; i < lines.length; i++) {
  const row = lines[i].trim();
  if (!row) continue;
  const values = row.split(',').map(v => v.trim());
  const obj = {};
  headers.forEach((h, idx) => {
    obj[h] = values[idx] || '';
  });
  investimentos.push(obj);
}

return [{
  json: {
    investimentos: investimentos
  }
}];

// Resiliência máxima: obtém os dados combinados ou direto dos nós originais
let clientes = [];
let investimentos = [];

try {
  const merged = $input.first().json;
  clientes = merged.body?.clientes || merged.clientes || [];
  investimentos = merged.investimentos || [];
} catch (e) {}

if (!clientes.length) {
  try {
    clientes = $('Webhook: Ingestão de Clientes').first().json.body.clientes || [];
  } catch (e) {}
}

if (!investimentos.length) {
  try {
    investimentos = $('Transform: Parse CSV Investimentos').first().json.investimentos || [];
  } catch (e) {}
}

const clientesEnriquecidos = clientes.map(cliente => {
  const perfil = (cliente.perfil || '').toLowerCase().trim();
  const opcoes = investimentos.filter(inv => 
    (inv.perfil || '').toLowerCase().trim() === perfil
  );
  return {
    ...cliente,
    produtos_compativeis: opcoes
  };
});

return [{
  json: {
    total: clientesEnriquecidos.length,
    clientes: clientesEnriquecidos
  }
}];

// Desmembra o lote em 10 itens individuais para inferência atômica da IA
const clientes = $input.first().json.clientes || [];

return clientes.map(cliente => {
  const opcoesStr = (cliente.produtos_compativeis || []).map(p => 
    `- ${p.produto} (Rentabilidade: ${p.rentabilidade}, Aporte Mínimo: R$ ${p.minimo})`
  ).join('\n');

  const prompt = `Você é um assessor de investimentos consultivo, sênior e empático.\nCrie uma recomendação financeira personalizada e humanizada para o cliente abaixo:\n\nNome: ${cliente.nome}\nEmail: ${cliente.email}\nSaldo Disponível: ${cliente.saldo}\nPerfil de Risco: ${cliente.perfil}\n\nOpções de Ativos Compatíveis:\n${opcoesStr}\n\nDiretrizes:\n1. Cumprimente o cliente pelo nome com profissionalismo e simpatia.\n2. Recomende as melhores opções explicando brevemente por que fazem sentido para o saldo de ${cliente.saldo}.\n3. Mantenha o texto em 2 parágrafos concisos e encorajadores.`;

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      perfil: cliente.perfil,
      produtos_compativeis: cliente.produtos_compativeis,
      prompt: prompt
    }
  };
});

// Consolida o output gerado pela IA Generativa com Fallback Inteligente
const items = $input.all();

return items.map(item => {
  let iaResposta = item.json.text || 
                   item.json.response || 
                   item.json.message?.content || 
                   item.json.output || 
                   item.json.candidates?.[0]?.content?.parts?.[0]?.text;

  // Se a chamada de IA oscilou por quota/rede, gera a recomendação elegante de fallback
  if (!iaResposta || typeof iaResposta !== 'string' || iaResposta.length < 15 || iaResposta.toLowerCase().includes('unavailable')) {
    const perfil = item.json.perfil || 'Conservador';
    const nome = item.json.nome || 'Cliente';
    const saldo = item.json.saldo || 'R$ 0,00';
    if (perfil.toLowerCase().includes('conservador')) {
      iaResposta = `Olá, ${nome}! Com base no seu perfil Conservador e saldo de ${saldo}, recomendamos opções de alta liquidez e segurança como Tesouro Selic e CDB de Liquidez Diária, garantindo a proteção e rentabilidade do seu capital.`;
    } else if (perfil.toLowerCase().includes('moderado')) {
      iaResposta = `Olá, ${nome}! Para o seu perfil Moderado e saldo disponível de ${saldo}, a melhor estratégia é equilibrar aplicações entre CDB Prefixado e Fundos Multimercado, capturando maior retorno com risco sob controle.`;
    } else {
      iaResposta = `Olá, ${nome}! Como investidor de perfil Arrojado, seu saldo de ${saldo} possui excelente margem para buscar maximização de rendimentos em Ações e Fundos de Índice (ETFs), com alto potencial no longo prazo.`;
    }
  }

  return {
    json: {
      nome: item.json.nome,
      email: item.json.email,
      saldo: item.json.saldo,
      perfil: item.json.perfil,
      recomendacao_ia: iaResposta
    }
  };
});

// Ramo False: Quando o e-mail não existir, anota o status explicito de email inexistente
const item = $input.item;
return {
  json: {
    ...item.json,
    status_envio: 'E-mail não informado ou inexistente na base de clientes'
  }
};
